async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let pending = "";
  let line = 1;
  let delivered = 0;

  function parseLine(text, lineNumber) {
    if (text.endsWith("\r")) text = text.slice(0, -1);
    if (/^\s*$/.test(text)) return null;

    try {
      return { value: JSON.parse(text) };
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }
  }

  async function processCompleteLines() {
    let newline;

    while ((newline = pending.indexOf("\n")) !== -1) {
      const text = pending.slice(0, newline);
      pending = pending.slice(newline + 1);

      const parsed = parseLine(text, line);
      line++;

      if (parsed !== null) {
        delivered++;
        if ((await deliver(parsed.value, line - 1)) === false) return false;
      }
    }

    return true;
  }

  try {
    for (;;) {
      const chunk = await input.read();

      if (chunk === null) break;

      pending += decoder.decode(chunk, { stream: true });
      if (!(await processCompleteLines())) return delivered;
    }

    pending += decoder.decode();

    if (pending.length > 0) {
      const parsed = parseLine(pending, line);

      if (parsed !== null) {
        delivered++;
        await deliver(parsed.value, line);
      }
    }

    return delivered;
  } finally {
    await input.close();
  }
}
